#include <Arduino.h>
#include <BLEDevice.h>
#include <BLEAdvertising.h>
#include <BLEBeacon.h>
#include "esp_bt.h"

// ----------------------------------------------------
// AUTO-BEACON
// ----------------------------------------------------

#define BEACON_UUID "74278BDA-B644-4520-8F0C-720EAF059935"

#define BEACON_MAJOR 1
#define BEACON_MINOR 1

void setup() {

  Serial.begin(115200);
  delay(500);

  Serial.println();
  Serial.println("================================");
  Serial.println("      AUTO BLE iBEACON");
  Serial.println("================================");

  // Bluetooth initialisieren
  BLEDevice::init("Auto-Beacon");

  // Maximale BLE-Sendeleistung
  esp_ble_tx_power_set(
    ESP_BLE_PWR_TYPE_ADV,
    ESP_PWR_LVL_P9
  );

  Serial.println("BLE TX Power: MAX");

  BLEBeacon beacon;

  // Apple iBeacon Manufacturer ID
  beacon.setManufacturerId(0x004C);

  // Eindeutige Kennung
  beacon.setProximityUUID(
    BLEUUID(BEACON_UUID)
  );

  // Fahrzeugkennung
  beacon.setMajor(BEACON_MAJOR);
  beacon.setMinor(BEACON_MINOR);

  // Kalibrierwert für 1 m
  beacon.setSignalPower(-59);

  BLEAdvertisementData advertisementData;

  advertisementData.setFlags(0x1A);

  advertisementData.setManufacturerData(
    beacon.getData()
  );

  BLEAdvertising *advertising =
    BLEDevice::getAdvertising();

  advertising->setAdvertisementData(
    advertisementData
  );

  advertising->start();

  Serial.println();
  Serial.println("iBeacon gestartet.");
  Serial.println();
  Serial.print("UUID : ");
  Serial.println(BEACON_UUID);
  Serial.print("Major: ");
  Serial.println(BEACON_MAJOR);
  Serial.print("Minor: ");
  Serial.println(BEACON_MINOR);
  Serial.println();
}

void loop() {
  // Beacon läuft selbstständig weiter.
  delay(1000);
}
